import java.util.Scanner;

public class main {

    // Inicia la granja y mantiene disponible el menú.
    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);
        GranjaRender granja = new GranjaRender();
        boolean continuar = true;

        // Carga los trabajos y nodos iniciales sin ingresos.
        cargarDatosIniciales(granja);

        // Repite el menú hasta que el usuario elija salir.
        while (continuar) {
            // Muestra las operaciones disponibles.
            mostrarMenu();

            try {
                int opcion = leerEntero(teclado, "Seleccione una opción: ");

                // Ejecuta la operación seleccionada.
                switch (opcion) {
                    case 1: {
                        Trabajo trabajo = leerTrabajo(teclado);

                        // Muestra la cotización sin guardar ni cobrar.
                        System.out.println(granja.cotizar(trabajo));
                        break;
                    }

                    case 2: {
                        Trabajo trabajo = leerTrabajo(teclado);

                        // Registra y cobra el trabajo.
                        granja.registrarTrabajo(trabajo);

                        // Muestra el monto registrado con dos decimales.
                        System.out.printf(
                            "Trabajo registrado. Cobro: Q%.2f%n",
                            trabajo.getIngresoRegistro()
                        );
                        break;
                    }

                    case 3: {
                        String codigo = leerTexto(
                            teclado, "Código del nodo: "
                        );
                        double capacidad = leerDecimal(
                            teclado, "Capacidad máxima en horas: "
                        );
                        boolean gpu = leerSiNo(
                            teclado, "¿Tiene GPU? (S/N): "
                        );

                        Nodo nodo = new Nodo(codigo, capacidad, gpu);

                        // Comprueba el código único y guarda el nodo.
                        granja.registrarNodo(nodo);

                        // Confirma el registro.
                        System.out.println("Nodo registrado.");
                        break;
                    }

                    case 4: {
                        String codigoNodo = leerTexto(
                            teclado, "Código del nodo: "
                        );

                        Lote lote = granja.crearLote(codigoNodo);

                        // Informa el código generado para el lote.
                        System.out.println(
                            "Lote creado: " + lote.getCodigo()
                        );
                        break;
                    }

                    case 5: {
                        String codigoLote = leerTexto(
                            teclado, "Código del lote: "
                        );
                        String codigoTrabajo = leerTexto(
                            teclado, "Código del trabajo: "
                        );

                        // Delega las validaciones y la asignación.
                        granja.asignarTrabajo(codigoLote, codigoTrabajo);

                        // Confirma la asignación.
                        System.out.println("Trabajo asignado.");
                        break;
                    }

                    case 6: {
                        String codigoLote = leerTexto(
                            teclado, "Código del lote: "
                        );
                        String codigoTrabajo = leerTexto(
                            teclado, "Código del trabajo: "
                        );

                        // Retira el trabajo y lo devuelve a la cola.
                        granja.retirarTrabajo(codigoLote, codigoTrabajo);

                        // Confirma el retiro.
                        System.out.println("Trabajo devuelto a la cola.");
                        break;
                    }

                    case 7: {
                        String codigoLote = leerTexto(
                            teclado, "Código del lote: "
                        );

                        // Inicia el lote y aplica los cargos por reintentos.
                        granja.iniciarLote(codigoLote);

                        // Confirma el inicio.
                        System.out.println("Lote iniciado.");
                        break;
                    }

                    case 8: {
                        String codigoLote = leerTexto(
                            teclado, "Código del lote: "
                        );
                        String codigoTrabajo = leerTexto(
                            teclado, "Código del trabajo: "
                        );
                        boolean completado = leerSiNo(
                            teclado,
                            "¿El trabajo se completó correctamente? (S/N): "
                        );

                        // Registra el resultado y cierra el lote si corresponde.
                        granja.registrarResultado(
                            codigoLote, codigoTrabajo, completado
                        );

                        // Muestra el estado resultante del trabajo.
                        System.out.println(
                            "Resultado registrado. Estado: "
                            + granja.buscarTrabajo(codigoTrabajo).getEstado()
                        );
                        break;
                    }

                    case 9: {
                        // Muestra los trabajos registrados.
                        System.out.println(granja.listarTrabajos());
                        break;
                    }

                    case 10: {
                        // Muestra los nodos registrados.
                        System.out.println(granja.listarNodos());
                        break;
                    }

                    case 11: {
                        // Muestra el conteo por categoría y estado.
                        System.out.println(
                            granja.contarPorCategoriaYEstado()
                        );
                        break;
                    }

                    case 12: {
                        // Muestra ingresos por registro, reintentos y categoría.
                        System.out.println(granja.reporteIngresos());
                        break;
                    }

                    case 13: {
                        // Muestra los lotes que todavía no están cerrados.
                        System.out.println(granja.reporteLotesAbiertos());
                        break;
                    }

                    case 0: {
                        // Termina el ciclo del menú.
                        continuar = false;

                        // Informa la salida del programa.
                        System.out.println("Programa finalizado.");
                        break;
                    }

                    default: {
                        // Informa que la opción no pertenece al menú.
                        System.out.println("Seleccione una opción válida.");
                        break;
                    }
                }
            } catch (IllegalArgumentException e) {
                // Informa errores de datos y permite continuar.
                System.out.println("Error: " + e.getMessage());
            } catch (IllegalStateException e) {
                // Informa operaciones que el estado actual no permite.
                System.out.println("Error: " + e.getMessage());
            }
        }

        // Cierra el lector al terminar el programa.
        teclado.close();
    }

    // Presenta las operaciones disponibles.
    public static void mostrarMenu() {
        // Imprime las opciones de la aplicación.
        System.out.println("\n===== RENDERGT =====");
        System.out.println("1. Cotizar trabajo");
        System.out.println("2. Registrar trabajo");
        System.out.println("3. Registrar nodo");
        System.out.println("4. Crear lote");
        System.out.println("5. Asignar trabajo a lote");
        System.out.println("6. Retirar trabajo de lote");
        System.out.println("7. Iniciar lote");
        System.out.println("8. Registrar resultado de trabajo");
        System.out.println("9. Consultar trabajos");
        System.out.println("10. Consultar nodos");
        System.out.println("11. Reporte por categoría y estado");
        System.out.println("12. Reporte de ingresos");
        System.out.println("13. Reporte de lotes abiertos");
        System.out.println("0. Salir");
    }

    // Lee los datos y construye un trabajo de la categoría seleccionada.
    private static Trabajo leerTrabajo(Scanner teclado) {
        // Presenta las categorías disponibles.
        System.out.println("\n1. Imagen fija");
        System.out.println("2. Animación");
        System.out.println("3. Animación con postproducción");
        System.out.println("4. Simulación física");

        int categoria = leerEntero(teclado, "Categoría: ");

        // Rechaza categorías inexistentes antes de pedir más datos.
        if (categoria < 1 || categoria > 4) {
            throw new IllegalArgumentException("Categoría inválida.");
        }

        String codigo = leerTexto(teclado, "Código del trabajo: ");
        String estudio = leerTexto(teclado, "Nombre del estudio: ");
        String proyecto = leerTexto(teclado, "Nombre del proyecto: ");
        double horas = leerDecimal(teclado, "Horas estimadas: ");
        Trabajo.Horario horario = leerHorario(teclado);

        // Construye la categoría; cada constructor valida sus datos.
        switch (categoria) {
            case 1: {
                // Crea una imagen fija.
                return new ImagenFija(
                    codigo, estudio, proyecto, horas, horario
                );
            }

            case 2: {
                int fotogramas = leerEntero(
                    teclado, "Cantidad de fotogramas: "
                );

                // Crea una animación.
                return new Animacion(
                    codigo, estudio, proyecto, horas, horario, fotogramas
                );
            }

            case 3: {
                int fotogramas = leerEntero(
                    teclado, "Cantidad de fotogramas: "
                );
                double recursos = leerDecimal(
                    teclado, "Valor de recursos licenciados en Q: "
                );

                // Crea una animación con postproducción.
                return new AnimacionPostProduccion(
                    codigo, estudio, proyecto, horas,
                    horario, fotogramas, recursos
                );
            }

            case 4: {
                double malla = leerDecimal(
                    teclado, "Resolución de malla en millones de celdas: "
                );

                // Crea una simulación física.
                return new SimulacionFisica(
                    codigo, estudio, proyecto, horas, horario, malla
                );
            }

            default: {
                // Evita devolver un trabajo si la categoría no es válida.
                throw new IllegalArgumentException("Categoría inválida.");
            }
        }
    }

    // Lee una línea de texto y elimina espacios en sus extremos.
    private static String leerTexto(Scanner teclado, String mensaje) {
        // Muestra qué dato se solicita.
        System.out.print(mensaje);

        // Lee la línea completa.
        return teclado.nextLine().trim();
    }

    // Lee un entero y repite la solicitud si el formato es incorrecto.
    private static int leerEntero(Scanner teclado, String mensaje) {
        // Mantiene la lectura hasta recibir un entero válido.
        while (true) {
            try {
                String entrada = leerTexto(teclado, mensaje);

                // Convierte la línea recibida a un entero.
                return Integer.parseInt(entrada);
            } catch (NumberFormatException e) {
                // Informa el problema sin terminar el programa.
                System.out.println(
                    "Entrada inválida. Escriba un número entero."
                );
            }
        }
    }

    // Lee un número decimal finito.
    private static double leerDecimal(Scanner teclado, String mensaje) {
        // Repite la solicitud mientras el formato sea incorrecto.
        while (true) {
            try {
                String entrada = leerTexto(teclado, mensaje);
                double valor = Double.parseDouble(entrada);

                // Rechaza infinito y NaN.
                if (!Double.isFinite(valor)) {
                    System.out.println(
                        "Escriba un número finito."
                    );
                } else {
                    // Los constructores validarán el rango permitido.
                    return valor;
                }
            } catch (NumberFormatException e) {
                // Explica el formato esperado.
                System.out.println(
                    "Entrada inválida. Use punto decimal, por ejemplo: 2.5"
                );
            }
        }
    }

    // Lee una respuesta S o N y la convierte a boolean.
    private static boolean leerSiNo(Scanner teclado, String mensaje) {
        // Repite la pregunta hasta recibir una respuesta válida.
        while (true) {
            String respuesta = leerTexto(teclado, mensaje);

            // Acepta la respuesta afirmativa sin distinguir mayúsculas.
            if (respuesta.equalsIgnoreCase("S")) {
                return true;
            } else if (respuesta.equalsIgnoreCase("N")) {
                // Convierte la respuesta negativa a false.
                return false;
            } else {
                // Informa las opciones permitidas.
                System.out.println("Responda S o N.");
            }
        }
    }

    // Permite seleccionar uno de los dos horarios.
    private static Trabajo.Horario leerHorario(Scanner teclado) {
        // Repite la selección hasta recibir una opción válida.
        while (true) {
            // Presenta los horarios.
            System.out.println("1. Diurno");
            System.out.println("2. Nocturno");

            int opcion = leerEntero(teclado, "Horario: ");

            // Devuelve el horario correspondiente.
            switch (opcion) {
                case 1:
                    return Trabajo.Horario.DIURNO;
                case 2:
                    return Trabajo.Horario.NOCTURNO;
                default:
                    // Informa una selección incorrecta.
                    System.out.println("Seleccione 1 o 2.");
                    break;
            }
        }
    }

    // Carga dos trabajos por categoría y tres nodos sin generar ingresos.
    private static void cargarDatosIniciales(GranjaRender granja) {
        // Agrega imágenes en ambos horarios.
        granja.agregarTrabajoInicial(
            new ImagenFija(
                "IF1", "Estudio Aurora", "Cartel", 1.5,
                Trabajo.Horario.DIURNO
            )
        );
        granja.agregarTrabajoInicial(
            new ImagenFija(
                "IF2", "Estudio Luna", "Interior", 2.0,
                Trabajo.Horario.NOCTURNO
            )
        );

        // Incluye el ejemplo donde las horas por fotogramas son mayores.
        granja.agregarTrabajoInicial(
            new Animacion(
                "AN1", "Estudio Aurora", "Cortometraje", 9.5,
                Trabajo.Horario.DIURNO, 610
            )
        );

        // Incluye una animación donde dominan las horas estimadas.
        granja.agregarTrabajoInicial(
            new Animacion(
                "AN2", "Estudio Luna", "Anuncio", 4.5,
                Trabajo.Horario.NOCTURNO, 100
            )
        );

        // Incluye el ejemplo de Q425 para postproducción.
        granja.agregarTrabajoInicial(
            new AnimacionPostProduccion(
                "AP1", "Estudio Prisma", "Escena final", 9.5,
                Trabajo.Horario.DIURNO, 610, 1800
            )
        );

        // Agrega postproducción en horario nocturno.
        granja.agregarTrabajoInicial(
            new AnimacionPostProduccion(
                "AP2", "Estudio Prisma", "Comercial", 3.0,
                Trabajo.Horario.NOCTURNO, 100, 500
            )
        );

        // Agrega simulaciones nocturnas con los límites de malla.
        granja.agregarTrabajoInicial(
            new SimulacionFisica(
                "SF1", "Estudio Agua", "Fluidos", 2.5,
                Trabajo.Horario.NOCTURNO, 1
            )
        );
        granja.agregarTrabajoInicial(
            new SimulacionFisica(
                "SF2", "Estudio Fuego", "Humo", 8.0,
                Trabajo.Horario.NOCTURNO, 50
            )
        );

        // Registra nodos con distintas capacidades y disponibilidad de GPU.
        granja.registrarNodo(new Nodo("N1", 10.0, false));
        granja.registrarNodo(new Nodo("N2", 20.0, true));
        granja.registrarNodo(new Nodo("N3", 5.0, false));
    }
}